        }

        STRONG = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            STRONG[i] = 1;
            for (int j = 1; j < i; j++) {
                STRONG[i] = (int)((STRONG[i] - (long)STRONG[j] * CP[i][j] % MOD + MOD) % MOD);
            }
        }

        ans = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            if (i < 2) {
                ans[i] = 0;
            } else {
