    static int modPow(int a, long e) {
        long res = 1;
        long base = a;
        while (e > 0) {
            if ((e & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return (int)res;
    }

    public static void main(String[] args) {
